INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01PUBDT1300000000000000000', '*', '', 'pp_doc13_exam_list', 'Liste des candidats au CEP ou au FSLC (DOC-13)', 'other', 'X', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["exam_label","school_year","list_state_label","candidates_block","totals_line"]', '2026-10-28T14:02:00+01:00', '2026-10-28T14:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT13F0000000000000000', '*', '', 'pp_doc13_exam_list', 'fr', '<html><body><style>@page{size:A4 landscape}pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:8px}</style><p>République du Cameroun · Ministère de l''Éducation de base</p><h1>{{establishment_name}}</h1><h2>Liste des candidats · {{exam_label}}</h2><p>Année scolaire {{school_year}} · État de la liste : {{list_state_label}}</p><pre>{{candidates_block}}</pre><p>{{totals_line}}</p><p>Un astérisque signale un ajout postérieur au gel, motivé et tracé.</p><p>Signatures : le directeur, l''inspecteur.</p><p>Fait le {{issued_on}} · N° {{number}}</p></body></html>', 1, '2026-10-28T14:02:00+01:00', NULL, '2026-10-28T14:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT13E0000000000000000', '*', '', 'pp_doc13_exam_list', 'en', '<html><body><style>@page{size:A4 landscape}pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:8px}</style><p>Republic of Cameroon · Ministry of Basic Education</p><h1>{{establishment_name}}</h1><h2>List of candidates · {{exam_label}}</h2><p>School year {{school_year}} · List status: {{list_state_label}}</p><pre>{{candidates_block}}</pre><p>{{totals_line}}</p><p>An asterisk marks an addition made after the freeze, with its recorded reason.</p><p>Signatures: the head teacher, the inspector.</p><p>Issued on {{issued_on}} · No. {{number}}</p></body></html>', 1, '2026-10-28T14:02:00+01:00', NULL, '2026-10-28T14:02:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01PUBDT1400000000000000000', '*', '', 'pp_doc14_candidate_sheet', 'Fiche individuelle de candidat (DOC-14)', 'other', 'N', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["exam_label","school_year","full_name","learner_number","sex_label","birth_line","birth_act_line","class_name","candidate_number","centre_label"]', '2026-10-28T14:02:00+01:00', '2026-10-28T14:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT14F0000000000000000', '*', '', 'pp_doc14_candidate_sheet', 'fr', '<html><body><style>.photo{border:1px solid #000}.photo{width:3.5cm}.photo{height:4.5cm}.photo{float:right}.photo{text-align:center}</style><p>République du Cameroun · Ministère de l''Éducation de base</p><h1>{{establishment_name}}</h1><h2>Fiche individuelle de candidat · {{exam_label}}</h2><div class="photo">Photo d''identité à coller</div><p>Année scolaire {{school_year}}</p><p>Nom et prénoms : {{full_name}}</p><p>Identifiant national : {{learner_number}}</p><p>Sexe : {{sex_label}} · Né(e) le : {{birth_line}}</p><p>Acte de naissance : {{birth_act_line}}</p><p>Classe : {{class_name}}</p><p>Numéro de candidat : {{candidate_number}} · Centre : {{centre_label}}</p><p>Signatures : le directeur, le parent ou tuteur.</p><p>Fait le {{issued_on}} · N° {{number}}</p></body></html>', 1, '2026-10-28T14:02:00+01:00', NULL, '2026-10-28T14:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT14E0000000000000000', '*', '', 'pp_doc14_candidate_sheet', 'en', '<html><body><style>.photo{border:1px solid #000}.photo{width:3.5cm}.photo{height:4.5cm}.photo{float:right}.photo{text-align:center}</style><p>Republic of Cameroon · Ministry of Basic Education</p><h1>{{establishment_name}}</h1><h2>Candidate record · {{exam_label}}</h2><div class="photo">Passport photo here</div><p>School year {{school_year}}</p><p>Full name: {{full_name}}</p><p>National pupil ID: {{learner_number}}</p><p>Sex: {{sex_label}} · Born on: {{birth_line}}</p><p>Birth certificate: {{birth_act_line}}</p><p>Class: {{class_name}}</p><p>Candidate number: {{candidate_number}} · Centre: {{centre_label}}</p><p>Signatures: the head teacher, the parent or guardian.</p><p>Issued on {{issued_on}} · No. {{number}}</p></body></html>', 1, '2026-10-28T14:02:00+01:00', NULL, '2026-10-28T14:02:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01PUBDT1500000000000000000', '*', '', 'pp_doc15_entrance_list', 'Liste des candidats à l''entrée en 6e ou au Common Entrance (DOC-15)', 'other', 'Y', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["exam_label","school_year","list_state_label","candidates_block","totals_line"]', '2026-10-28T14:02:00+01:00', '2026-10-28T14:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT15F0000000000000000', '*', '', 'pp_doc15_entrance_list', 'fr', '<html><body><style>@page{size:A4 landscape}pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:8px}</style><p>République du Cameroun · Ministère de l''Éducation de base</p><h1>{{establishment_name}}</h1><h2>Candidats au concours · {{exam_label}}</h2><p>Année scolaire {{school_year}} · État de la liste : {{list_state_label}}</p><pre>{{candidates_block}}</pre><p>{{totals_line}}</p><p>Format de l''organisateur à confirmer (Q10).</p><p>Signature : le directeur.</p><p>Fait le {{issued_on}} · N° {{number}}</p></body></html>', 1, '2026-10-28T14:02:00+01:00', NULL, '2026-10-28T14:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT15E0000000000000000', '*', '', 'pp_doc15_entrance_list', 'en', '<html><body><style>@page{size:A4 landscape}pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:8px}</style><p>Republic of Cameroon · Ministry of Basic Education</p><h1>{{establishment_name}}</h1><h2>Entrance examination candidates · {{exam_label}}</h2><p>School year {{school_year}} · List status: {{list_state_label}}</p><pre>{{candidates_block}}</pre><p>{{totals_line}}</p><p>Organiser format to be confirmed (Q10).</p><p>Signature: the head teacher.</p><p>Issued on {{issued_on}} · No. {{number}}</p></body></html>', 1, '2026-10-28T14:02:00+01:00', NULL, '2026-10-28T14:02:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01PUBDT1600000000000000000', '*', '', 'pp_doc16_attestation', 'Attestation de réussite au CEP ou au FSLC (DOC-16)', 'other', 'Z', '{CODE}-{AA}-{LETTRE}-{N6}', 1, 0, '["exam_label","school_year","full_name","learner_number","birth_line","candidate_number","signer_label"]', '2026-10-28T14:02:00+01:00', '2026-10-28T14:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT16F0000000000000000', '*', '', 'pp_doc16_attestation', 'fr', '<html><body><p>République du Cameroun · Ministère de l''Éducation de base · Délégation départementale</p><h1>Attestation de réussite</h1><h2>{{exam_label}}</h2><p>Le délégué départemental atteste que {{full_name}}, identifiant national {{learner_number}}, né(e) le {{birth_line}}, élève de {{establishment_name}}, candidat n° {{candidate_number}}, a été déclaré(e) admis(e) à la session {{school_year}}, d''après les résultats officiels publiés.</p><p><strong>La présente attestation ne tient pas lieu de diplôme. Le diplôme est délivré par l''autorité compétente.</strong></p><p>Signature manuscrite et cachet du délégué départemental ({{signer_label}}) :</p><div>{{signature}}{{stamp}}</div><p>Préparée le {{issued_on}} · N° {{number}}</p><div class="qr">{{qr}}</div></body></html>', 1, '2026-10-28T14:02:00+01:00', NULL, '2026-10-28T14:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT16E0000000000000000', '*', '', 'pp_doc16_attestation', 'en', '<html><body><p>Republic of Cameroon · Ministry of Basic Education · Divisional Delegation</p><h1>Certificate of success (attestation)</h1><h2>{{exam_label}}</h2><p>The Divisional Delegate certifies that {{full_name}}, national pupil ID {{learner_number}}, born on {{birth_line}}, pupil of {{establishment_name}}, candidate No. {{candidate_number}}, passed the {{school_year}} session according to the official published results.</p><p><strong>This attestation is not a diploma. The diploma is issued by the competent authority.</strong></p><p>Handwritten signature and stamp of the Divisional Delegate ({{signer_label}}):</p><div>{{signature}}{{stamp}}</div><p>Prepared on {{issued_on}} · No. {{number}}</p><div class="qr">{{qr}}</div></body></html>', 1, '2026-10-28T14:02:00+01:00', NULL, '2026-10-28T14:02:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01PUBDT1700000000000000000', '*', '', 'pp_doc17_exam_results', 'Relevé des résultats d''examen de l''école (DOC-17)', 'other', 'S', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["exam_label","school_year","results_block","summary_line"]', '2026-10-28T14:02:00+01:00', '2026-10-28T14:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT17F0000000000000000', '*', '', 'pp_doc17_exam_results', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:8px}</style><p>République du Cameroun · Ministère de l''Éducation de base</p><h1>{{establishment_name}}</h1><h2>Relevé des résultats · {{exam_label}}</h2><p>Année scolaire {{school_year}}</p><pre>{{results_block}}</pre><p>{{summary_line}}</p><p>Résultats officiels importés. Signature : le directeur.</p><p>Fait le {{issued_on}} · N° {{number}}</p></body></html>', 1, '2026-10-28T14:02:00+01:00', NULL, '2026-10-28T14:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT17E0000000000000000', '*', '', 'pp_doc17_exam_results', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:8px}</style><p>Republic of Cameroon · Ministry of Basic Education</p><h1>{{establishment_name}}</h1><h2>Examination results · {{exam_label}}</h2><p>School year {{school_year}}</p><pre>{{results_block}}</pre><p>{{summary_line}}</p><p>Official imported results. Signature: the head teacher.</p><p>Issued on {{issued_on}} · No. {{number}}</p></body></html>', 1, '2026-10-28T14:02:00+01:00', NULL, '2026-10-28T14:02:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01PUBDT2600000000000000000', '*', '', 'pub_doc26_visit_report', 'Rapport de visite d''inspection (DOC-26)', 'other', 'I', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["visit_date","inspector_name","class_name","teacher_name","grid_label","answers_block","headcount_line","observations","recommendations_block","followups_block"]', '2026-10-28T14:02:00+01:00', '2026-10-28T14:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT26F0000000000000000', '*', '', 'pub_doc26_visit_report', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:8px}</style><p>République du Cameroun · Ministère de l''Éducation de base · Inspection</p><h1>{{establishment_name}}</h1><h2>Rapport de visite</h2><p>Visite du {{visit_date}} · Par {{inspector_name}}</p><p>Classe : {{class_name}} · Enseignant : {{teacher_name}} · Grille : {{grid_label}}</p><pre>{{answers_block}}</pre><p>Contrôle des effectifs : {{headcount_line}}</p><p>Observations : {{observations}}</p><h3>Recommandations</h3><pre>{{recommendations_block}}</pre><h3>Suivi des recommandations précédentes</h3><pre>{{followups_block}}</pre><p>Transmis à l''enseignant et au directeur. Signature : l''inspecteur.</p><p>Fait le {{issued_on}} · N° {{number}}</p></body></html>', 1, '2026-10-28T14:02:00+01:00', NULL, '2026-10-28T14:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT26E0000000000000000', '*', '', 'pub_doc26_visit_report', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:8px}</style><p>Republic of Cameroon · Ministry of Basic Education · Inspectorate</p><h1>{{establishment_name}}</h1><h2>Visit report</h2><p>Visit of {{visit_date}} · By {{inspector_name}}</p><p>Class: {{class_name}} · Teacher: {{teacher_name}} · Grid: {{grid_label}}</p><pre>{{answers_block}}</pre><p>Headcount check: {{headcount_line}}</p><p>Observations: {{observations}}</p><h3>Recommendations</h3><pre>{{recommendations_block}}</pre><h3>Follow-up of previous recommendations</h3><pre>{{followups_block}}</pre><p>Sent to the teacher and the head teacher. Signature: the inspector.</p><p>Issued on {{issued_on}} · No. {{number}}</p></body></html>', 1, '2026-10-28T14:02:00+01:00', NULL, '2026-10-28T14:02:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01PUBDT2800000000000000000', '*', '', 'pub_doc28_territory_dashboard', 'Tableau de bord territorial (DOC-28)', 'other', 'G', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["territory_label","reference_date","indicators_block","objectives_block","masking_line"]', '2026-10-28T14:02:00+01:00', '2026-10-28T14:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT28F0000000000000000', '*', '', 'pub_doc28_territory_dashboard', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:8px}</style><p>République du Cameroun · Ministère de l''Éducation de base</p><h1>Tableau de bord territorial</h1><h2>{{territory_label}}</h2><p>Données agrégées au {{reference_date}} · aucune donnée nominative</p><pre>{{indicators_block}}</pre><h3>Objectifs du programme</h3><pre>{{objectives_block}}</pre><p>{{masking_line}}</p><p>Édité le {{issued_on}} · N° {{number}}</p></body></html>', 1, '2026-10-28T14:02:00+01:00', NULL, '2026-10-28T14:02:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT28E0000000000000000', '*', '', 'pub_doc28_territory_dashboard', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:8px}</style><p>Republic of Cameroon · Ministry of Basic Education</p><h1>Territorial dashboard</h1><h2>{{territory_label}}</h2><p>Aggregated data as of {{reference_date}} · no named data</p><pre>{{indicators_block}}</pre><h3>Programme objectives</h3><pre>{{objectives_block}}</pre><p>{{masking_line}}</p><p>Issued on {{issued_on}} · No. {{number}}</p></body></html>', 1, '2026-10-28T14:02:00+01:00', NULL, '2026-10-28T14:02:00+01:00');
